('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00053','CHAPITRE 2 : L’ÉLÉMENT MATÉRIEL',53,'_Paragraph','c’est la manifestation concrète de la volonté délictueuse du délinquant.','c’est la manifestation concrète de la volonté délictueuse du délinquant.','{}'::jsonb,true),
