('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00120','2.2.2.1 — Définition',120,'_SubTitle','2.2.2.1 — Définition','2.2.2.1 — Définition','{}'::jsonb,true),
