('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00149','3.2.2 — La faute non intentionnelle',149,'_Paragraph','L’individu ne recherche aucun résultat particulier, mais ne respecte pas les valeurs sociales protégées pénalement.','L’individu ne recherche aucun résultat particulier, mais ne respecte pas les valeurs sociales protégées pénalement.','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00150','3.2.2.1 — La faute d’imprudence ou de négligence',150,'_SubTitle','3.2.2.1 — La faute d’imprudence ou de négligence','3.2.2.1 — La faute d’imprudence ou de négligence','{}'::jsonb,true),
