('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00152','3.2.2.1 — La faute d’imprudence ou de négligence',152,'_SubTitle',' dispose qu’elle consiste en une imprudence, négligence ou manquement à une obligation de prudence ou de sécurité prévue par la loi ou le règlement.',' dispose qu’elle consiste en une imprudence, négligence ou manquement à une obligation de prudence ou de sécurité prévue par la loi ou le règlement.','{}'::jsonb,true),
