('lib/content/gpx_scolarite/dps_dpg/droit_pénale_général_pages/gpx_school_elements_constitutifs_infraction_page.dart','f00155','3.2.2.1.1 — Formes de la faute',155,'_SubTitle','3.2.2.1.1 — Formes de la faute','3.2.2.1.1 — Formes de la faute','{}'::jsonb,true),
